import 'package:flutter/material.dart';
class PrivacyScreen extends StatelessWidget{const PrivacyScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('PRIVACY POLICY')),body:const SingleChildScrollView(padding:EdgeInsets.all(20),child:Text('''Lane Rush: Traffic Escape stores game progress such as coins, best score, unlocked cars and settings locally on the device. The app does not require an account or login.\n\nAdvertising: the app supports optional rewarded ads and limited interstitial ads through Google Mobile Ads. Test ad IDs are enabled in this starter build and must be replaced before publishing. Advertising providers may process device and advertising information according to their policies.\n\nPurchases: optional digital purchases are processed by Google Play. The app does not receive full payment-card details.\n\nLocal data may be removed if the app is uninstalled or its storage is cleared. Consumable coin purchases are not cloud-synced by this no-login version.\n\nBefore production release, update this policy with your developer contact, live AdMob configuration and the exact Play Data Safety disclosures.''' ,style:TextStyle(height:1.6,color:Colors.white70))));}
